    private IQueryable<SubscriptionPaymentResponse> PaymentQuery()=>from payment in db.SubscriptionPaymentRequests.AsNoTracking() join contract in db.SubscriptionContracts.AsNoTracking() on payment.SubscriptionContractId equals contract.Id join customer in db.CustomerProfiles.AsNoTracking() on payment.CustomerProfileId equals customer.Id join service in db.ServiceCategories.AsNoTracking() on contract.ServiceCategoryId equals service.Id join method0 in db.SubscriptionPaymentMethods.AsNoTracking() on payment.PaymentMethodId equals method0.Id into methods from method in methods.DefaultIfEmpty() orderby payment.RequestedAt descending select new SubscriptionPaymentResponse(payment.PublicId,contract.PublicId,Number("SC",contract.PublicId),customer.DisplayName,service.Name,payment.BillingPeriodStart,payment.BillingPeriodEnd,payment.RequestedAmount,payment.CurrencyCode,payment.StatusCode,method==null?null:method.MaskedDisplayText,payment.RequestedAt,payment.CompletedAt,payment.FailureReason,Version(payment.RowVersion));
    private Task<SubscriptionPaymentResponse> Payment(Guid id,CancellationToken token)=>PaymentQuery().SingleAsync(x=>x.Id==id,token);
