    private void AddPayoutEvent(SubscriptionPayout payout,string type,object data,long? actor,string key,DateTime now)=>db.SubscriptionPayoutEvents.Add(new SubscriptionPayoutEvent{SubscriptionPayoutId=payout.Id,EventTypeCode=type,EventDataJson=JsonSerializer.Serialize(data),OccurredAt=now,ActorUserId=actor,IdempotencyKey=key});
    private void Audit(long actor,string action,string entity,Guid? id,object? before,object? after,string? reason=null)=>db.AuditLogs.Add(new AuditLog{OccurredAt=DateTime.UtcNow,ActorUserId=actor,ActorRoleCode=RoleCodes.Admin,ActionCode=action,EntityType=entity,EntityPublicId=id,ResultCode="SUCCESS",Reason=reason,BeforeJson=before is null?null:JsonSerializer.Serialize(before),AfterJson=after is null?null:JsonSerializer.Serialize(after)});
    private async Task<long> AdminId(Guid id,CancellationToken token)=>await(from user in db.Users join link in db.UserRoles on user.Id equals link.UserId join role in db.Roles on link.RoleId equals role.Id where user.PublicId==id&&user.StatusCode=="ACTIVE"&&link.RevokedAt==null&&role.Code==RoleCodes.Admin select(long?)user.Id).SingleOrDefaultAsync(token)??throw Forbidden("ADMIN_REQUIRED","관리자 계정을 확인할 수 없습니다.");
    private async Task<bool> IsSettlementPaymentClear(long contractId,DateOnly visitDate,CancellationToken token){var paymentId=await db.SubscriptionPaymentRequests.AsNoTracking().Where(x=>x.SubscriptionContractId==contractId&&x.StatusCode=="COMPLETED"&&x.BillingPeriodStart<=visitDate&&x.BillingPeriodEnd>=visitDate).OrderByDescending(x=>x.CompletedAt).Select(x=>(long?)x.Id).FirstOrDefaultAsync(token);if(!paymentId.HasValue)return false;return !await db.SubscriptionRefundAdjustments.AsNoTracking().AnyAsync(x=>x.PaymentRequestId==paymentId&&(x.StatusCode=="REQUESTED"||x.StatusCode=="APPROVED"||x.StatusCode=="PROCESSING"||x.StatusCode=="COMPLETED"),token);}
    private static decimal? VisitAmount(string json){try{using var doc=JsonDocument.Parse(json);return doc.RootElement.TryGetProperty("visitAmount",out var value)&&value.TryGetDecimal(out var amount)?amount:null;}catch(JsonException){return null;}}
    private static decimal? BillingAmount(string json){try{using var doc=JsonDocument.Parse(json);var root=doc.RootElement;if(root.TryGetProperty("monthlyAmount",out var monthly)&&monthly.ValueKind!=JsonValueKind.Null&&monthly.TryGetDecimal(out var monthlyAmount))return monthlyAmount;if(root.TryGetProperty("visitAmount",out var visit)&&visit.ValueKind!=JsonValueKind.Null&&visit.TryGetDecimal(out var visitAmount))return visitAmount;return null;}catch(JsonException){return null;}}
    private static void ValidatePaymentMethod(RegisterSubscriptionPaymentMethodRequest input){var type=input.PaymentMethodTypeCode.Trim().ToUpperInvariant();if(type is not ("CARD" or "BANK" or "EASY_PAY" or "OTHER"))throw Bad("SUBSCRIPTION_PAYMENT_METHOD_TYPE_INVALID","결제수단 유형을 확인해 주세요.");var reference=input.ExternalTokenReference??string.Empty;if(Regex.IsMatch(reference,@"(?:\d[ -]?){12,19}")||reference.Contains("cvc",StringComparison.OrdinalIgnoreCase)||reference.Contains("cvv",StringComparison.OrdinalIgnoreCase))throw Bad("SUBSCRIPTION_PAYMENT_SENSITIVE_DATA_REJECTED","카드번호·CVC·계좌 비밀번호 등 민감 결제정보는 저장할 수 없습니다.");}
    private void EnsureSimulation(string code,string message){if(!SimulationAvailable)throw new SubscriptionBusinessException(StatusCodes.Status404NotFound,code,message);}
    private static void EnsureVersion(byte[] current,string supplied){try{if(!current.SequenceEqual(Convert.FromBase64String(supplied)))throw new FormatException();}catch{throw Conflict("SUBSCRIPTION_CONCURRENCY_CONFLICT","다른 작업이 먼저 처리했습니다. 최신 상태를 다시 확인해 주세요.");}}
    private static void RequiredKey(string key){if(string.IsNullOrWhiteSpace(key))throw Bad("SUBSCRIPTION_IDEMPOTENCY_KEY_REQUIRED","중복 처리 방지 키가 필요합니다.");}
    private static void ValidateMonth(int year,int month){if(year<2000||year>2200||month<1||month>12)throw Bad("SUBSCRIPTION_SETTLEMENT_MONTH_INVALID","정산 연월을 확인해 주세요.");}
    private static string? Trim(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
    private static string Version(byte[] value)=>Convert.ToBase64String(value);
    private static string Number(string prefix,Guid id)=>$"{prefix}-{id.ToString("N")[..10].ToUpperInvariant()}";
    private static SubscriptionBusinessException Bad(string code,string message)=>new(StatusCodes.Status400BadRequest,code,message);
    private static SubscriptionBusinessException Forbidden(string code,string message)=>new(StatusCodes.Status403Forbidden,code,message);
    private static SubscriptionBusinessException NotFound(string code,string message)=>new(StatusCodes.Status404NotFound,code,message);
    private static SubscriptionBusinessException Conflict(string code,string message)=>new(StatusCodes.Status409Conflict,code,message);
}
